with filtered_transactions as (select * from transactions where is_flagged and (txn_type in ('CREDIT', 'DEBIT', 'REFUND') or is_flagged)), Summary as (select to_date(txn_time) as txn_day, case when amount >= 3200 then 'high' when amount >= 1500 then 'mid' else 'low' end as amount_bucket, sum(amount) as total_amount from filtered_transactions group by to_date(txn_time), case when amount >= 3200 then 'high' when amount >= 1500 then 'mid' else 'low' end) select txn_day, amount_bucket, total_amount from Summary order by amount_bucket, txn_day desc
